import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import { clsx } from 'clsx';
import type { JSX } from 'solid-js';
import { splitProps } from 'solid-js';
import { Dynamic } from 'solid-js/web';
import styles from './Text.module.css';

const elements = {
  div: ark.div,
  em: ark.em,
  p: ark.p,
  small: ark.small,
  span: ark.span,
  strong: ark.strong,
} as const;

type TextElement = 'p' | 'span' | 'small' | 'strong' | 'em' | 'div';
type TextSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';
type TextWeight = 'regular' | 'medium' | 'semibold' | 'bold';
type TextTone = 'default' | 'muted' | 'subtle' | 'primary' | 'destructive';
type TextAlign = 'start' | 'center' | 'end' | 'left' | 'right' | 'justify';
type TextProps = HTMLArkProps<'p'> & {
  as?: TextElement;
  size?: TextSize;
  weight?: TextWeight;
  tone?: TextTone;
  align?: TextAlign;
  truncate?: boolean;
  lineClamp?: number;
  'data-scope'?: string;
  'data-part'?: string;
  'data-slot'?: string;
  'data-size'?: string;
  'data-weight'?: string;
  'data-tone'?: string;
  'data-align'?: string;
  'data-truncate'?: string;
  'data-line-clamp'?: string;
};

function Text(props: TextProps) {
  const [local, others] = splitProps(props, [
    'as',
    'asChild',
    'size',
    'weight',
    'tone',
    'align',
    'truncate',
    'lineClamp',
    'class',
    'style',
    'data-scope',
    'data-part',
    'data-slot',
    'data-size',
    'data-weight',
    'data-tone',
    'data-align',
    'data-truncate',
    'data-line-clamp',
  ]);
  const Element = () => elements[local.as ?? 'p'] as typeof ark.p;
  const defaultSize = () => (local.as === 'small' ? 'sm' : 'md');
  const defaultWeight = () => (local.as === 'strong' ? 'semibold' : 'regular');
  const resolvedLineClamp = () =>
    Number.isInteger(local.lineClamp) && (local.lineClamp ?? 0) > 0 ? local.lineClamp : undefined;
  const lineClampStyle = (): JSX.CSSProperties | string | undefined => {
    const value = resolvedLineClamp();

    if (value === undefined) return local.style;
    if (typeof local.style === 'string') {
      return `${local.style};--_text-line-clamp:${value}`;
    }

    return { ...local.style, '--_text-line-clamp': value };
  };

  return (
    <Dynamic
      component={Element()}
      asChild={local.asChild}
      {...others}
      data-scope="text"
      data-part="root"
      data-slot="text-root"
      data-size={local.size ?? defaultSize()}
      data-weight={local.weight ?? defaultWeight()}
      data-tone={local.tone ?? 'default'}
      data-align={local.align}
      data-truncate={local.truncate ? '' : undefined}
      data-line-clamp={resolvedLineClamp() === undefined ? undefined : ''}
      class={clsx(styles.root, local.class)}
      style={lineClampStyle()}
    />
  );
}

export { Text };

@layer moduix.components {
  .root {
    margin: 0;
    font-family: var(--moduix-text-font-family, inherit);
    font-size: var(--moduix-text-font-size-md, var(--moduix-text-md));
    font-weight: var(--moduix-text-font-weight-regular, var(--moduix-weight-regular));
    line-height: var(--moduix-text-line-height-md, var(--moduix-line-height-text-md));
    letter-spacing: var(--moduix-text-letter-spacing, 0);
    color: var(--moduix-text-default-color, var(--moduix-color-foreground));
    text-align: start;
    overflow-wrap: anywhere;

    &[data-size='xs'] {
      font-size: var(--moduix-text-font-size-xs, var(--moduix-text-xs));
      line-height: var(--moduix-text-line-height-xs, var(--moduix-line-height-text-xs));
    }

    &[data-size='sm'] {
      font-size: var(--moduix-text-font-size-sm, var(--moduix-text-sm));
      line-height: var(--moduix-text-line-height-sm, var(--moduix-line-height-text-sm));
    }

    &[data-size='lg'] {
      font-size: var(--moduix-text-font-size-lg, var(--moduix-text-lg));
      line-height: var(--moduix-text-line-height-lg, var(--moduix-line-height-text-lg));
    }

    &[data-size='xl'] {
      font-size: var(--moduix-text-font-size-xl, var(--moduix-text-xl));
      line-height: var(--moduix-text-line-height-xl, var(--moduix-line-height-text-xl));
    }

    &[data-weight='medium'] {
      font-weight: var(--moduix-text-font-weight-medium, var(--moduix-weight-medium));
    }

    &[data-weight='semibold'] {
      font-weight: var(--moduix-text-font-weight-semibold, var(--moduix-weight-semibold));
    }

    &[data-weight='bold'] {
      font-weight: var(--moduix-text-font-weight-bold, var(--moduix-weight-bold));
    }

    &[data-tone='muted'] {
      color: var(--moduix-text-muted-color, var(--moduix-color-muted-foreground));
    }

    &[data-tone='subtle'] {
      color: var(--moduix-text-subtle-color, var(--moduix-color-secondary-foreground));
    }

    &[data-tone='primary'] {
      color: var(--moduix-text-primary-color, var(--moduix-color-primary));
    }

    &[data-tone='destructive'] {
      color: var(--moduix-text-destructive-color, var(--moduix-color-destructive));
    }

    &[data-align='left'] {
      text-align: left;
    }

    &[data-align='start'] {
      text-align: start;
    }

    &[data-align='center'] {
      text-align: center;
    }

    &[data-align='right'] {
      text-align: right;
    }

    &[data-align='end'] {
      text-align: end;
    }

    &[data-align='justify'] {
      text-align: justify;
    }

    &[data-truncate] {
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    &[data-line-clamp] {
      --_text-line-clamp: initial;

      display: -webkit-box;
      overflow: hidden;
      white-space: normal;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: var(--moduix-text-line-clamp, var(--_text-line-clamp));
    }
  }
}
